def find_solution(a, b, n):
    if a == 0 and b == 0:
        return n == 0 and (0, 0)
    if a == 0:
        return n % b == 0 and (n // b, 0)
    if b == 0:
        return n % a == 0 and (n // a, 0)
    if a < 0:
        a, b, n = -a, -b, -n
    if b < 0:
        b, n = -b, -n
    if n < 0:
        return None
    if n == 0:
        return (0, 0)
    if a > b:
        q, r = divmod(a, b)
        if r == 0:
            return (n // b, 0)
        return find_solution(b, r, n)
    if b > a:
        q, r = divmod(b, a)
        if r == 0:
            return (0, n // a)
        return find_solution(a, r, n)
    return None
```

