def max_sum_increasing_subseq(arr, i, k, j):
    if k < i or k >= len(arr):
        return 0
    if j < i or j >= len(arr):
        return 0
    if k == j:
        return arr[k]
    if arr[k] <= arr[j]:
        return arr[k]
    return arr[k] + max(
        max_sum_increasing_subseq(arr, i, k, j),
        max_sum_increasing_subseq(arr, i, k, j - 1)
    )
```

